package br.com.gameshelf.controller;
import br.com.gameshelf.dto.JogoDtos.DashboardResponse;import br.com.gameshelf.repository.UsuarioRepository;import br.com.gameshelf.service.JogoService;import org.springframework.security.core.Authentication;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final JogoService service;private final UsuarioRepository usuarios;public DashboardController(JogoService s,UsuarioRepository u){service=s;usuarios=u;}@GetMapping public DashboardResponse obter(Authentication a){Long id=usuarios.findByEmail(((UserDetails)a.getPrincipal()).getUsername()).orElseThrow().getId();return service.dashboard(id);}}
